        await using (var bind = new NpgsqlCommand("SELECT EXISTS(SELECT 1 FROM platform.agents a JOIN platform.endpoints e ON e.tenant_id=a.tenant_id AND e.id=a.endpoint_id WHERE a.tenant_id=$1 AND a.id=$2 AND a.endpoint_id=$3 AND a.instance_id=$4 AND a.status='active' AND e.status NOT IN('disabled','revoked'))", c, tx)) { bind.Parameters.AddWithValue(tenant); bind.Parameters.AddWithValue(batch.AgentId); bind.Parameters.AddWithValue(batch.EndpointId); bind.Parameters.AddWithValue(batch.InstallationId); if ((bool)(await bind.ExecuteScalarAsync(ct) ?? false) == false) throw new EnrollmentConflictException("NETWORK_IDENTITY_INVALID", "Network telemetry identity is invalid or disabled."); }
