    public async Task<NetworkObservation?> GetEventAsync(string tenant, Guid id, CancellationToken ct) { await using var c = await _data.OpenConnectionAsync(ct); await using var cmd = new NpgsqlCommand("SELECT event_data FROM platform.network_events WHERE tenant_id=$1 AND event_id=$2", c); cmd.Parameters.AddWithValue(Guid.Parse(tenant)); cmd.Parameters.AddWithValue(id); var v = await cmd.ExecuteScalarAsync(ct); return v is null ? null : JsonSerializer.Deserialize<NetworkObservation>((string)v, Json); }
    public async Task<NetworkConnectionView?> GetConnectionAsync(string tenant, Guid endpoint, string id, CancellationToken ct) { await using var c = await _data.OpenConnectionAsync(ct); await using var cmd = new NpgsqlCommand("SELECT tenant_id::text,endpoint_id,connection_entity_id,process_entity_id,protocol,address_family,local_endpoint,remote_endpoint,direction,first_observed,last_observed,attempted_at,established_at,failed_at,closed_at,duration_milliseconds,state,latest_event_id,source_confidence,data_quality_flags,lifecycle_completeness,latest_process,user_identity,hostname_context FROM platform.network_connection_entities WHERE tenant_id=$1 AND endpoint_id=$2 AND connection_entity_id=$3", c); cmd.Parameters.AddWithValue(Guid.Parse(tenant)); cmd.Parameters.AddWithValue(endpoint); cmd.Parameters.AddWithValue(id); await using var r = await cmd.ExecuteReaderAsync(ct); return await r.ReadAsync(ct) ? ReadConnection(r) : null; }
    static NetworkConnectionView ReadConnection(NpgsqlDataReader r) => new(r.GetString(0), r.GetGuid(1), r.GetString(2), r.IsDBNull(3) ? null : r.GetString(3), r.GetString(4), r.GetString(5), JsonSerializer.Deserialize<NetworkSocketEndpoint>(r.GetString(6), Json)!, r.IsDBNull(7) ? null : JsonSerializer.Deserialize<NetworkSocketEndpoint>(r.GetString(7), Json), Enum.Parse<NetworkDirection>(r.GetString(8), true), r.GetFieldValue<DateTimeOffset>(9), r.GetFieldValue<DateTimeOffset>(10), r.IsDBNull(11) ? null : r.GetFieldValue<DateTimeOffset>(11), r.IsDBNull(12) ? null : r.GetFieldValue<DateTimeOffset>(12), r.IsDBNull(13) ? null : r.GetFieldValue<DateTimeOffset>(13), r.IsDBNull(14) ? null : r.GetFieldValue<DateTimeOffset>(14), r.IsDBNull(15) ? null : r.GetInt64(15), Enum.Parse<NetworkConnectionState>(r.GetString(16), true), r.GetGuid(17), r.GetString(18), r.GetFieldValue<string[]>(19), Enum.Parse<NetworkLifecycleCompleteness>(r.GetString(20), true), r.IsDBNull(21) ? null : JsonSerializer.Deserialize<NetworkProcessRelationship>(r.GetString(21), Json), r.IsDBNull(22) ? null : r.GetString(22), r.IsDBNull(23) ? null : JsonSerializer.Deserialize<NetworkHostnameContext>(r.GetString(23), Json));
    async Task<NetworkEventPage> History(string tenant, Guid endpoint, DateTimeOffset from, DateTimeOffset to, int limit, string predicate, string id, CancellationToken ct) { await using var c = await _data.OpenConnectionAsync(ct); await using var cmd = new NpgsqlCommand($"SELECT event_data FROM platform.network_events WHERE tenant_id=$1 AND endpoint_id=$2 AND observed_at BETWEEN $3 AND $4 AND {predicate} ORDER BY observed_at,event_id LIMIT $6", c); object[] v = [Guid.Parse(tenant), endpoint, from, to, id, Math.Clamp(limit, 1, 500)]; foreach (var x in v) cmd.Parameters.AddWithValue(x); var list = new List<NetworkObservation>(); await using var r = await cmd.ExecuteReaderAsync(ct); while (await r.ReadAsync(ct)) list.Add(JsonSerializer.Deserialize<NetworkObservation>(r.GetString(0), Json)!); return new(list, null); }
    public Task<NetworkEventPage> ConnectionHistoryAsync(string tenant, Guid endpoint, string id, DateTimeOffset from, DateTimeOffset toInclusive, int limit, CancellationToken ct) => History(tenant, endpoint, from, toInclusive, limit, "connection_entity_id=$5", id, ct);
    public Task<NetworkEventPage> ProcessNetworkAsync(string tenant, Guid endpoint, string id, DateTimeOffset from, DateTimeOffset toInclusive, int limit, CancellationToken ct) => History(tenant, endpoint, from, toInclusive, limit, "process_entity_id=$5", id, ct);
    public Task<NetworkEventPage> EndpointTimelineAsync(string tenant, Guid endpoint, NetworkSearchRequest q, CancellationToken ct) => SearchAsync(tenant, q with { EndpointId = endpoint }, ct);
    public async Task<NetworkConnectionPage> ListenersAsync(string tenant, Guid endpoint, int limit, CancellationToken ct) { await using var c = await _data.OpenConnectionAsync(ct); await using var cmd = new NpgsqlCommand("SELECT tenant_id::text,endpoint_id,connection_entity_id,process_entity_id,protocol,address_family,local_endpoint,remote_endpoint,direction,first_observed,last_observed,attempted_at,established_at,failed_at,closed_at,duration_milliseconds,state,latest_event_id,source_confidence,data_quality_flags,lifecycle_completeness,latest_process,user_identity,hostname_context FROM platform.network_connection_entities WHERE tenant_id=$1 AND endpoint_id=$2 AND state='listening' ORDER BY last_observed DESC LIMIT $3", c); cmd.Parameters.AddWithValue(Guid.Parse(tenant)); cmd.Parameters.AddWithValue(endpoint); cmd.Parameters.AddWithValue(Math.Clamp(limit, 1, 500)); var list = new List<NetworkConnectionView>(); await using var r = await cmd.ExecuteReaderAsync(ct); while (await r.ReadAsync(ct)) list.Add(ReadConnection(r)); return new(list, null); }
    public async Task<NetworkTelemetryHealth?> HealthAsync(string tenant, Guid endpoint, CancellationToken ct) { await using var c = await _data.OpenConnectionAsync(ct); await using var cmd = new NpgsqlCommand("SELECT health_data FROM platform.network_telemetry_health WHERE tenant_id=$1 AND endpoint_id=$2", c); cmd.Parameters.AddWithValue(Guid.Parse(tenant)); cmd.Parameters.AddWithValue(endpoint); var v = await cmd.ExecuteScalarAsync(ct); return v is null ? null : JsonSerializer.Deserialize<NetworkTelemetryHealth>((string)v, Json); }
    public async Task<IReadOnlyList<NetworkObservation>> ListAllAsync(CancellationToken ct) { await using var c = await _data.OpenConnectionAsync(ct); await using var cmd = new NpgsqlCommand("SELECT tenant_id::text,event_data FROM platform.network_events ORDER BY observed_at,event_id", c); var list = new List<NetworkObservation>(); await using var r = await cmd.ExecuteReaderAsync(ct); while (await r.ReadAsync(ct)) { var x = JsonSerializer.Deserialize<NetworkObservation>(r.GetString(1), Json)!; list.Add(x with { CorrelationId = $"tenant:{r.GetString(0)}" }); } return list; }
    public ValueTask DisposeAsync() => _data.DisposeAsync();
